            <tr><td className="px-3 py-2 text-xs">6</td><td className="px-3 py-2 text-xs">岩手県</td><td className="px-3 py-2 text-xs">189件</td><td className="px-3 py-2 text-xs">河川敷での人身被害および公園・学校周辺出没</td></tr>
